using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public sealed class RateCache
{
    private readonly Dictionary<string, decimal> _rates = new();
    private readonly IRateApi _api;

    public RateCache(IRateApi api) => _api = api;

    public async Task<decimal> GetRateAsync(string pair)
    {
        if (_rates.TryGetValue(pair, out var cached))
        {
            return cached;
        }

        var rate = await _api.FetchAsync(pair);
        _rates[pair] = rate;
        return rate;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public sealed class Basket
{
    public required IReadOnlyList<Reservation> Items { get; init; }

    /// <summary>True when every reservation in the basket is still valid.</summary>
    public bool IsStillValid()
    {
        return Items.Any(item => item.ExpiresAtUtc > DateTime.Now);
    }
}

public sealed record Reservation(string Sku, DateTime ExpiresAtUtc);
